WITH flattened_attrs AS (SELECT id, host, log_ts, level, status_code, payload_json, context['version'] AS version, COALESCE(context['region'], 'unknown') AS region_or_default, GET_JSON_OBJECT(payload_json, '$.duration') AS duration_text FROM app_logs) SELECT *, LEAD(status_code, 2) OVER (PARTITION BY host, level ORDER BY log_ts, id) AS next_status_code, LEAD(status_code, 1, 0) OVER (PARTITION BY level ORDER BY log_ts, id) AS next_status_code_2 FROM flattened_attrs;
